#!/usr/bin/env python3
"""Soccer with policies trained by reinforcement learning (PPO). One node drives the 3 robots.

Generated by rl/export_soccer.py (attackers: soccer_att_a2w; keeper: script).
Do not edit by hand: train again and export. Documentation: rl/docs/documentacao.md

Roles inside the team: first robot = defender / keeper, the other two = attackers.
  attackers: MLP 28 -> 128 -> 128 -> 2 (tanh), one network shared by both robots
  defender:  MLP 28 -> 128 -> 128 -> 2 (tanh), or the scripted keeper if not exported
Everything is computed in the team frame (red sees the field rotated by 180 deg), so the
same file plays blue or red (~team). Only standard Python, numpy, rospy, the ROS messages
and psr_hero.utils are used.

Run:  ./run.sh run soccer blue:=soccer_rl.py red:=none
"""
import base64
import json
import math

import numpy as np
import rospy
from geometry_msgs.msg import Twist
from nav_msgs.msg import Odometry
from std_msgs.msg import String

from psr_hero.utils import V_MAX, W_MAX, clamp, pose_from_odom, wrap_angle

TEAMS = {"blue": (0, +1), "red": (3, -1)}
CONTROL_HZ = 20
HALF_L, HALF_W, GOAL_HALF = 0.9, 0.6, 0.20  # field 1.8 x 1.2 m, goal 0.40 m
USE_UNJAM = False  # rule-based jam supervisor on top of the attacker network (see class Unjam)


# --- observation (copied from rl/soccer_obs.py) --------------------------------
def team_frame_np(p, flip):
    """(x, y, yaw, v, w) of a robot in the team frame (flip=True for the red team)."""
    if not flip:
        return p
    yaw = (p[2] + 2.0 * math.pi) % (2.0 * math.pi) - math.pi
    return (-p[0], -p[1], yaw, p[3], p[4])


def observation_np(mine, theirs, ball, role, prev):
    """mine, theirs: 3 tuples (x, y, yaw, v, w) in the team frame (mine in role order);
    ball: (x, y, vx, vy) in the team frame; prev: (lin, ang). Returns a list of 28 floats."""
    me = mine[role]
    c, s = math.cos(me[2]), math.sin(me[2])

    def rel(px, py):
        dx, dy = px - me[0], py - me[1]
        return c * dx + s * dy, -s * dx + c * dy

    bx, by = rel(ball[0], ball[1])
    bvx, bvy = c * ball[2] + s * ball[3], -s * ball[2] + c * ball[3]
    gx, gy = rel(HALF_L, 0.0)
    ox, oy = rel(-HALF_L, 0.0)
    m = [rel(mine[k][0], mine[k][1]) for k in range(3) if k != role]
    op = sorted((rel(t[0], t[1]) for t in theirs), key=lambda q: q[0] * q[0] + q[1] * q[1])
    out = [me[0] / HALF_L, me[1] / HALF_W, c, s, me[3] / V_MAX, me[4] / W_MAX,
           bx, by, ball[0] / HALF_L, ball[1] / HALF_W, bvx / 0.5, bvy / 0.5,
           gx / 1.8, gy / 1.8, ox / 1.8, oy / 1.8, m[0][0], m[0][1], m[1][0], m[1][1]]
    for q in op:
        out += [q[0], q[1]]
    return out + [float(prev[0]), float(prev[1])]


