def _load(name):
    shape, chunks = WEIGHTS[name]
    return np.frombuffer(base64.b64decode("".join(chunks)), dtype="<f4").reshape(shape).astype(np.float64)


class Policy:
    """Deterministic actor (mean of the Gaussian policy)."""

    def __init__(self, prefix, n_layers):
        self.mean = _load(prefix + "norm_mean")
        self.std = np.sqrt(_load(prefix + "norm_var") + 1e-5)
        self.layers = [(_load(prefix + "W%d" % j), _load(prefix + "b%d" % j)) for j in range(n_layers)]

    def __call__(self, obs):
        x = np.clip((np.asarray(obs, dtype=np.float64) - self.mean) / self.std, -5.0, 5.0)
        for j, (w, b) in enumerate(self.layers):
            x = w.dot(x) + b
            if j < len(self.layers) - 1:
                x = np.tanh(x)
        return np.clip(x, -1.0, 1.0)


def keeper_script(me, ball):
    """Scripted keeper (team frame): goal line, y = ball y clipped to the goal mouth."""
    ty = clamp(ball[1], -GOAL_HALF + 0.03, GOAL_HALF - 0.03)
    dx, dy = (-HALF_L + 0.07) - me[0], ty - me[1]
    if math.hypot(dx, dy) < 0.03:
        return 0.0, clamp(4.0 * wrap_angle(math.atan2(ball[1] - me[1], ball[0] - me[0]) - me[2]), -W_MAX, W_MAX)
    err = wrap_angle(math.atan2(dy, dx) - me[2])
    return (V_MAX if abs(err) < 0.5 else 0.0), clamp(4.0 * err, -W_MAX, W_MAX)


def go_to(me, tx, ty):
    err = wrap_angle(math.atan2(ty - me[1], tx - me[0]) - me[2])
    return (V_MAX if abs(err) < 0.5 else 0.0), clamp(4.0 * err, -W_MAX, W_MAX)


def push_to(me, ball, gx, gy, behind=0.08):
    """Get behind the ball on the line ball -> (gx, gy) and push it there (team frame)."""
    ux, uy = gx - ball[0], gy - ball[1]
    d = max(math.hypot(ux, uy), 1e-6)
    ux, uy = ux / d, uy / d
    bx, by = ball[0] - behind * ux, ball[1] - behind * uy
    rx, ry = ball[0] - me[0], ball[1] - me[1]
    along, cross = rx * ux + ry * uy, -rx * uy + ry * ux
    if along > 0.02 and abs(cross) < 0.035:
        tx, ty = ball[0] + 0.10 * ux, ball[1] + 0.10 * uy
    elif along < 0:
        side = -1.0 if cross > 0 else 1.0
        tx, ty = bx + side * 0.09 * -uy, by + side * 0.09 * ux
    else:
        tx, ty = bx, by
    return go_to(me, clamp(tx, -HALF_L + 0.04, HALF_L - 0.04), clamp(ty, -HALF_W + 0.04, HALF_W - 0.04))


class Unjam:
    """Rule-based supervisor on top of the attacker network (hybrid controller).

    A jam = the ball moved less than JAM_DIST in JAM_S seconds (it happens against the walls,
    where the network gets stuck and nothing in the game resets it). Then, for MANEUVER_S
    seconds, the attacker closest to the ball pushes it ALONG the wall, towards the opponent
    side and away from the corner, and the other one lines up behind it and pushes too (two
    against one); after that the network takes over again (COOLDOWN_S before a new maneuver)."""

    JAM_S, JAM_DIST, MANEUVER_S, COOLDOWN_S = 3.0, 0.03, 2.5, 2.0

    def __init__(self):
        self.ref, self.t_ref, self.until, self.ready_at, self.target = None, 0.0, -1.0, 0.0, None

    def update(self, ball, now):
        """ball in the team frame. Returns the push target (x, y) while a maneuver is active, else None."""
        if self.ref is None or math.hypot(ball[0] - self.ref[0], ball[1] - self.ref[1]) > self.JAM_DIST:
            self.ref, self.t_ref = (ball[0], ball[1]), now
        if now < self.until:
            return self.target
        if now - self.t_ref > self.JAM_S and now >= self.ready_at:
            # along the nearest wall, towards +x (their side); in a corner of their side, towards the goal
            tx, ty = clamp(ball[0] + 0.35, -HALF_L + 0.1, HALF_L - 0.1), ball[1]
            if abs(ball[1]) < HALF_W - 0.08 and abs(ball[0]) > HALF_L - 0.08:  # against an end wall
                ty = 0.0
                tx = ball[0] + (0.3 if ball[0] < 0 else -0.05)
            elif ball[0] > HALF_L - 0.25:  # long wall near their goal: towards the goal mouth
                tx, ty = HALF_L, 0.0
            self.target = (tx, ty)
            self.until, self.ready_at = now + self.MANEUVER_S, now + self.MANEUVER_S + self.COOLDOWN_S
            self.ref, self.t_ref = (ball[0], ball[1]), now
            return self.target
        return None


# --- telemetria para os logs do torneio ---------------------------------------
# A cada TEL_PERIOD s (relógio do ROS) escreve no log uma linha "TEL {json}" com a
# posição de todos os robôs, bola/bandeiras, estado do jogo e o comando enviado.
# Mudanças de placar/estado do jogo saem na hora como "EVT {json}", e os parâmetros
# do nó saem uma vez como "TELINIT {json}". Os logs aparecem em api/log do site
# do torneio. Isso só gera log: o comportamento do robô continua igual.
TIPO = "rl"
TEL_PERIOD = 1.0  # s entre linhas TEL; 0 desliga (site guarda ~400 linhas)
TEL_IGNORAR = ("field", "ring_radius", "base_x", "base_radius")  # constantes: não vão para o log
TEL_RELOGIO = ("t", "time", "round_time", "held", "message")  # não disparam EVT (vêm junto de placar/tags)


def _tel_r(p, n=3):
    """Arredonda (x, y[, yaw, ...]) para caber no log; None continua None."""
    if p is None:
        return None
    return [round(float(x), n) for x in p]


class Telemetria:
    def __init__(self, period=TEL_PERIOD):
        self.period, self.last, self.ultimo_jogo, self.t0 = period, -1e9, None, None
        self.init, self.eventos = None, True  # eventos=False: este nó não escreve EVT

    @staticmethod
    def _log(tag, campos):
        try:
            rospy.loginfo("%s %s", tag, json.dumps(campos, separators=(",", ":")))
        except Exception as e:  # nunca derrubar o nó por causa do log
            rospy.logwarn_throttle(10.0, "telemetria: %s" % e)

    def inicio(self, eventos=True, **campos):
        self.init, self.eventos = campos, eventos

    def __call__(self, now, game=None, **campos):
        if self.period <= 0:
            return
        if self.t0 is None:
            self.t0 = now
            if self.init is not None:
                self._log("TELINIT", self.init)
        t = round(now - self.t0, 2)  # s desde o início do nó
        game = {k: v for k, v in (game or {}).items() if k not in TEL_IGNORAR}
        chave = json.dumps({k: v for k, v in game.items() if k not in TEL_RELOGIO}, sort_keys=True)
        if self.eventos and self.ultimo_jogo is not None and chave != self.ultimo_jogo:
            self._log("EVT", dict(t=t, jogo=game))
        self.ultimo_jogo = chave
        if now - self.last < self.period:
            return
        self.last = now
        self._log("TEL", dict(t=t, jogo=game, **campos))


class Soccer:
    def __init__(self):
        rospy.init_node("soccer")
        team = rospy.get_param("~team", "blue")
        self.first, self.attack = TEAMS[team]
        self.flip = self.attack < 0
        self.ids = [self.first + k for k in range(3)]
        self.opp_ids = [i for i in range(6) if i not in self.ids]
        self.poses = {}  # id -> (x, y, yaw), world frame
        self.vel = {}  # id -> (v, w)
        self.ball = None  # (x, y)
        self.ball_v = (0.0, 0.0)
        self.prev = [(0.0, 0.0)] * 3
        self.score = None
        self.att = Policy("att_", 3)
        self.dfn = Policy("def_", 0) if 0 else None
        self.unjam = Unjam() if USE_UNJAM else None
        self.now = 0.0  # simulated time of the last command (rospy.get_time() in ROS)
        self.game = {}  # último /game/state (telemetria)
        self.tel = Telemetria()
        self.tel.inicio(jogo="soccer", tipo=TIPO, team=team, ids=self.ids, opp_ids=self.opp_ids)

        self.pubs = {i: rospy.Publisher("/hero_%d/cmd_vel" % i, Twist, queue_size=1) for i in self.ids}
        for i in range(6):
            rospy.Subscriber("/hero_%d/odom" % i, Odometry, self.on_odom, callback_args=i, queue_size=1)
        rospy.Subscriber("/ball/odom", Odometry, self.on_ball, queue_size=1)
        rospy.Subscriber("/game/state", String, self.on_game, queue_size=1)

    def on_odom(self, msg, i):
        self.poses[i] = pose_from_odom(msg)
        self.vel[i] = (msg.twist.twist.linear.x, msg.twist.twist.angular.z)

    def on_ball(self, msg):
        self.ball = (msg.pose.pose.position.x, msg.pose.pose.position.y)
        self.ball_v = (msg.twist.twist.linear.x, msg.twist.twist.linear.y)

    def on_game(self, msg):
        try:
            self.game = json.loads(msg.data)
        except (ValueError, TypeError):
            pass
        # after a goal everybody goes back to the kickoff: restart the previous actions
        try:
            st = json.loads(msg.data)
            s = (int(st.get("blue", 0)), int(st.get("red", 0)))
        except (ValueError, TypeError, AttributeError):
            return
        if self.score is not None and s != self.score:
            self.prev = [(0.0, 0.0)] * 3
        self.score = s

    def robot(self, i):
        x, y, yaw = self.poses[i]
        v, w = self.vel.get(i, (0.0, 0.0))
        return team_frame_np((x, y, yaw, v, w), self.flip)

    def compute_commands(self, poses, ball):
        """Three (linear_x, angular_z), one per robot of self.ids (keeper first)."""
        mine = [self.robot(i) for i in self.ids]
        theirs = [self.robot(i) for i in self.opp_ids]
        s = -1.0 if self.flip else 1.0
        b = (s * ball[0], s * ball[1], s * self.ball_v[0], s * self.ball_v[1])
        target = self.unjam.update(b, self.now) if self.unjam is not None else None
        if target is not None:
            d1 = math.hypot(mine[1][0] - b[0], mine[1][1] - b[1])
            d2 = math.hypot(mine[2][0] - b[0], mine[2][1] - b[1])
            near = 1 if d1 <= d2 else 2
        out = []
        for role in range(3):
            if target is not None and role in (1, 2):
                # both attackers push the same way: the second one lines up behind the first and adds its
                # force (two against one breaks a stalemate with an opponent of equal traction)
                v, w = push_to(mine[role], b, target[0], target[1], behind=0.08 if role == near else 0.16)
                self.prev[role] = (v / V_MAX, w / W_MAX)
                out.append((v, w))
                continue
            if role == 0 and self.dfn is None:
                v, w = keeper_script(mine[0], b)
                self.prev[0] = (v / V_MAX, w / W_MAX)
                out.append((v, w))
                continue
            net = self.dfn if role == 0 else self.att
            a = net(observation_np(mine, theirs, b, role, self.prev[role]))
            self.prev[role] = (float(a[0]), float(a[1]))
            out.append((float(a[0]) * V_MAX, float(a[1]) * W_MAX))
        return out

    def run(self):
        rate = rospy.Rate(CONTROL_HZ)
        while not rospy.is_shutdown():
            if self.ball is None or len(self.poses) < 6:
                rospy.logwarn_throttle(2.0, "waiting for odometry and ball")
            else:
                self.now = rospy.get_time()
                cmds = self.compute_commands(self.poses, self.ball)
                for i, (v, w) in zip(self.ids, cmds):
                    cmd = Twist()
                    cmd.linear.x, cmd.angular.z = v, w
                    self.pubs[i].publish(cmd)
                self.tel(self.now, self.game, ball=_tel_r(tuple(self.ball) + tuple(self.ball_v)),
                         robots={i: _tel_r(tuple(self.poses[i]) + tuple(self.vel.get(i, (0.0, 0.0))))
                                 for i in sorted(self.poses)},
                         cmd={i: _tel_r(c) for i, c in zip(self.ids, cmds)})
            rate.sleep()


if __name__ == "__main__":
    Soccer().run()
